'use strict';
const SITE='https://ariana-s.vercel.app';
const products=[
{id:'samsa',name:'Самса',category:'piece',tag:'Поштучно',unit:'шт.',image:'samsa-photo',description:'Румяная выпечка к обеду, чаю и хорошему разговору.'},
{id:'pies',name:'Домашний пирог',category:'pie',tag:'К общему столу',unit:'пирог',image:'pie',description:'Для семейного чаепития и встречи с друзьями.'},
{id:'sweet',name:'Выпечка к чаю',category:'piece',tag:'Поштучно',unit:'шт.',image:'tea',description:'Маленькая радость для сладкой паузы в течение дня.'},
{id:'newyear',name:'Новогодний набор',category:'set',tag:'Новый год',unit:'набор',image:'christmas',description:'Праздничное настроение в подарочной коробке.'},
{id:'halloween',name:'Набор к Хэллоуину',category:'set',tag:'Хэллоуин',unit:'набор',image:'halloween',description:'Осенний набор для тех, кто любит сладкие сюрпризы.'},
{id:'party',name:'К большому столу',category:'set',tag:'Для компании',unit:'набор',image:'gathering',description:'Сытная выпечка для вечера в хорошей компании.'},
{id:'celebration',name:'Праздничный набор',category:'set',tag:'Особенный день',unit:'набор',image:'cake-photo',description:'Вкусный подарок ко дню рождения или другому тёплому поводу.'}];
const $=s=>document.querySelector(s);const storage=window.ArianaPrivacy.storage;
let cart={};const savedCart=storage.read('arianas-cart',{});for(const p of products){const n=Number(savedCart?.[p.id]);if(Number.isInteger(n)&&n>0&&n<=99)cart[p.id]=n}let profile=storage.read('arianas-profile',{});if(!profile||typeof profile!=='object')profile={};let orders=storage.read('arianas-orders',[]);if(!Array.isArray(orders))orders=[];orders=orders.filter(o=>o&&typeof o.text==='string'&&typeof o.id==='string').slice(0,30);let currentFilter='all',activeOrder=null,toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function open(id){const dialog=document.getElementById(id);if(!dialog)return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(id==='cart'){editOrder();prefill();$('#orderDate').min=today()}if(id==='account'){renderAccount();switchTab('profile')}dialog.showModal();document.body.classList.add('modal-open')}
for(const b of document.querySelectorAll('[data-open]'))b.onclick=()=>open(b.dataset.open);for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>b.closest('dialog').close();for(const d of document.querySelectorAll('dialog')){d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open')});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})}
function renderProducts(){const query=$('#search').value.trim().toLocaleLowerCase('ru');const result=products.filter(p=>(currentFilter==='all'||p.category===currentFilter)&&`${p.name} ${p.description} ${p.tag}`.toLocaleLowerCase('ru').includes(query));$('#products').replaceChildren();if(!result.length){const p=document.createElement('p');p.className='no-results';p.textContent='Ничего не нашлось. Попробуйте «самса», «набор» или «пирог».';$('#products').append(p)}for(const p of result){const article=document.createElement('article');article.className='product card';article.dataset.product=p.id;const picture=['tea','gathering'].includes(p.image)?`<img src="/assets/${p.image}.webp" alt="${p.name}" loading="lazy" width="1400" height="933">`:p.image==='pie'?'<img src="/assets/bakery.webp" alt="Пирог на праздничном столе" loading="lazy">':`<div class="atlas ${p.image}" role="img" aria-label="${p.name}"></div>`;article.innerHTML=`<div class="product-picture">${picture}</div><div class="product-info"><span class="product-meta">${p.tag}</span><h3>${p.name}</h3><p>${p.description}</p><div class="product-bottom"><small>${p.unit==='шт.'?'Поштучно':p.unit==='пирог'?'Целый пирог':'Набор'}</small><button class="add" aria-label="Добавить: ${p.name}">В корзину</button></div></div>`;article.querySelector('button').onclick=()=>add(p.id);$('#products').append(article)}}
function add(id){if((cart[id]||0)>=99){toast('Укажите количество для большого заказа в пожеланиях.');return}cart[id]=(cart[id]||0)+1;activeOrder=null;updateCount();toast(`${products.find(p=>p.id===id).name} в корзине`)}
function updateCount(persist=true){const count=Object.values(cart).reduce((a,b)=>a+b,0);$('#count').textContent=count;$('#dockCount').textContent=count;if(persist){if(Object.keys(cart).length)storage.write('arianas-cart',cart);else storage.remove('arianas-cart')}}
function renderCart(){const items=products.filter(p=>cart[p.id]);$('#cartItems').replaceChildren();if(!items.length){const empty=document.createElement('div');empty.className='empty';empty.innerHTML='Выберите что-нибудь вкусное<small>Выпечка поштучно, домашние пироги и праздничные наборы.</small><button class="button outline" style="margin-top:24px">Открыть меню</button>';empty.querySelector('button').onclick=()=>{$('#cart').close();location.hash='catalog'};$('#cartItems').append(empty);$('#checkout').hidden=true;return}$('#checkout').hidden=false;for(const p of items){const row=document.createElement('div');row.className='cart-row';row.innerHTML=`<div class="cart-description"><strong>${p.name}</strong><small>${p.unit==='шт.'?'Поштучно':p.unit==='пирог'?'Целый пирог':'Набор'}</small></div><div class="quantity-control"><label>Количество<input type="number" inputmode="numeric" min="1" max="99" step="1" value="${cart[p.id]}" aria-label="Количество: ${p.name}"></label><button class="remove-item" aria-label="Убрать: ${p.name}">Убрать</button></div>`;const input=row.querySelector('input');input.onchange=()=>{const n=Number(input.value);if(!Number.isInteger(n)||n<1||n>99){input.value=cart[p.id];toast('Укажите количество от 1 до 99.');return}cart[p.id]=n;activeOrder=null;updateCount();renderCart()};row.querySelector('button').onclick=()=>{delete cart[p.id];activeOrder=null;updateCount();renderCart()};$('#cartItems').append(row)}$('#quantitySummary').textContent=String(Object.values(cart).reduce((a,b)=>a+b,0))}
function today(){const d=new Date;return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function prefill(){if(!$('#orderName').value.trim()&&typeof profile.name==='string')$('#orderName').value=profile.name;if(!$('#orderContact').value.trim()&&typeof profile.contact==='string')$('#orderContact').value=profile.contact}
function editOrder(){$('#orderResult').hidden=true;$('.cart-layout').hidden=false;renderCart()}$('#editOrder').onclick=editOrder;
$('#checkout').onsubmit=e=>{e.preventDefault();const name=$('#orderName').value.trim(),contact=$('#orderContact').value.trim(),date=$('#orderDate').value;if(!Object.keys(cart).length)return;if(!name||!contact){toast('Укажите имя и контакт для связи.');return}if(date<today()){toast('Выберите сегодняшнюю или будущую дату.');return}const text=['Здравствуйте, Ариана! Хочу заказать:','',...products.filter(p=>cart[p.id]).map(p=>`${p.name}: ${cart[p.id]} ${p.unit}`),'',`К дате: ${date.split('-').reverse().join('.')}`,`Получение: ${$('#fulfilment').value}`,`Имя: ${name}`,`Связь: ${contact}`,`Пожелания: ${$('#orderNotes').value.trim()||'Нет особых пожеланий'}`,'','Подскажите стоимость и удобное время получения.'].join('\n');const id=activeOrder||`AR-${Date.now().toString(36).toUpperCase()}`;activeOrder=id;const record={id,text,name,date,created:new Date().toISOString(),quantity:Object.values(cart).reduce((a,b)=>a+b,0)};orders=[record,...orders.filter(o=>o.id!==id)].slice(0,30);const persisted=storage.write('arianas-orders',orders);showOrder(text);renderAccount();if(!persisted)toast('Не удалось сохранить заказ. Скопируйте его текст.')};
function showOrder(text){$('#orderText').value=text;$('#telegramOrder').href=`https://t.me/share/url?url=${encodeURIComponent(SITE)}&text=${encodeURIComponent(text)}`;$('.cart-layout').hidden=true;$('#orderResult').hidden=false}
async function copyText(value,success,field){try{await navigator.clipboard.writeText(value);toast(success)}catch{if(field){field.focus();field.select();toast('Выделили текст. Выберите «Копировать».')}else toast('Ссылка на пекарню: ariana-s.vercel.app')}}
$('#copyOrder').onclick=()=>copyText($('#orderText').value,'Текст заказа скопирован.',$('#orderText'));$('#copyLink').onclick=()=>copyText(SITE,'Ссылка скопирована.');
$('.filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;currentFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-pressed',String(n===b))});renderProducts()};$('#search').oninput=renderProducts;for(const b of document.querySelectorAll('[data-browse]'))b.onclick=()=>{currentFilter='all';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(n=>{const active=n.dataset.filter==='all';n.classList.toggle('active',active);n.setAttribute('aria-pressed',String(active))});renderProducts();const target=document.querySelector(`[data-product="${b.dataset.browse}"]`);target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});target.querySelector('button').focus({preventScroll:true})};$('#shareTg').href=`https://t.me/share/url?url=${encodeURIComponent(SITE)}&text=${encodeURIComponent('Домашняя выпечка Ariana’s')}`;$('#shareVk').href=`https://vk.com/share.php?url=${encodeURIComponent(SITE)}`;
function switchTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#profile').hidden=tab!=='profile';$('#history').hidden=tab!=='orders'}for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>switchTab(b.dataset.tab);
function renderAccount(){const name=typeof profile.name==='string'?profile.name:'';$('#profileName').value=name;$('#profileContact').value=typeof profile.contact==='string'?profile.contact:'';$('#greeting').textContent=name?`Привет, ${name}!`:'Добро пожаловать';$('#avatar').textContent=name?name[0].toUpperCase():'A';$('#ordersCount').textContent=orders.length;$('#history').replaceChildren();if(!orders.length){const empty=document.createElement('p');empty.className='subnote';empty.textContent='Сохранённые заказы появятся здесь.';$('#history').append(empty)}for(const o of orders){const article=document.createElement('article');article.className='history-card';const title=document.createElement('strong');title.textContent=`Заказ к ${String(o.date||'').split('-').reverse().join('.')}`;const status=document.createElement('small');status.textContent='Сохранён для отправки';const p=document.createElement('p');p.textContent=`Количество: ${Number(o.quantity)||0}`;const button=document.createElement('button');button.className='button outline';button.textContent='Открыть заказ';button.onclick=()=>{open('cart');showOrder(o.text)};article.append(title,status,p,button);$('#history').append(article)}}
$('#profile').onsubmit=e=>{e.preventDefault();const name=$('#profileName').value.trim(),contact=$('#profileContact').value.trim();if(!name||!contact){toast('Укажите имя и контакт.');return}profile={name,contact};const saved=storage.write('arianas-profile',profile);$('#orderName').value=name;$('#orderContact').value=contact;renderAccount();toast(saved?(window.ArianaPrivacy.get().personal?'Профиль сохранён на этом устройстве.':'Профиль применён на время посещения.'):'Не удалось сохранить профиль на устройстве.')};
$('#mobileMenu').onclick=()=>{const hidden=!$('#mobileNav').hidden;$('#mobileNav').hidden=hidden;$('#mobileMenu').setAttribute('aria-expanded',String(!hidden))};$('#mobileNav').addEventListener('click',e=>{if(e.target.closest('a,button')){$('#mobileNav').hidden=true;$('#mobileMenu').setAttribute('aria-expanded','false')}});$('#backTop').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});window.addEventListener('scroll',()=>$('#backTop').classList.toggle('visible',scrollY>500),{passive:true});renderProducts();updateCount(false);renderAccount();

function updateStorageHint(){document.getElementById('profileStorageHint').textContent=window.ArianaPrivacy.get().personal?'Профиль и история сохраняются в этом браузере на срок до 90 дней.':'Сейчас профиль и история доступны только до перезагрузки страницы.'}
updateStorageHint();
window.addEventListener('arianas-privacy-change',()=>{updateStorageHint();if(Object.keys(cart).length)storage.write('arianas-cart',cart);if(Object.keys(profile).length)storage.write('arianas-profile',profile);if(orders.length)storage.write('arianas-orders',orders)});
window.addEventListener('arianas-data-cleared',()=>{cart={};profile={};orders=[];activeOrder=null;document.getElementById('checkout').reset();document.getElementById('profile').reset();document.getElementById('orderText').value='';document.getElementById('telegramOrder').removeAttribute('href');updateCount();renderCart();renderAccount();editOrder();updateStorageHint();toast('Корзина, профиль и история удалены с устройства.')});
